INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_sdm_222', (SELECT id FROM catalog.course WHERE public_id = 'sql-data-modeling'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'sql-data-modeling') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-sdm-2-2' AND is_deleted = false LIMIT 1), 'spot-the-ai-mistake-double-counting', 'Spot the AI Mistake: double counting', 'A developer asked an AI assistant to "count learners and completed lessons per course" for the course dashboard and shipped the query after checking one small course. Since then instructors report learner counts higher than the enrollment list (a learner who finished three lessons is counted three times), and the new course "Docker Basics", which has no learners yet, is missing from the dashboard.

Fix QUERY so that it returns one row per course, every course included: [course_id, title, learners, completed_lessons], ordered by course_id.
- learners = number of enrollments of the course whose status is not ''cancelled''.
- completed_lessons = number of lesson_progress rows with a non-NULL completed_at for the lessons of the course (NULL = started, not finished).
- Both numbers are 0, never NULL, when there is nothing to count.
The runner loads each test''s rows into SQLite (foreign keys on), runs QUERY and prints the rows as JSON.', 'open', 'easy'::difficulty_question, 'fix_bug', 30, true, false)
