-- challenge chal_quiz_sdm_231 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_sdm_231', (SELECT id FROM catalog.course WHERE public_id = 'sql-data-modeling'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'sql-data-modeling') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-sdm-2-3' AND is_deleted = false LIMIT 1), 'progress-aggregates-quiz', 'Read the progress numbers the way SQLite computes them', 'Two results from the CodeDev progress incident: what COUNT counts after a LEFT JOIN, and what integer division does to a percentage. Decide whether each statement is true or false.', 'open', 'easy'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_sdm_231');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_sdm_231'), 'courses has two rows: (10, ''SQL Basics'') and (40, ''Kubernetes Basics''). lessons has three rows, all with course_id = 10. Course 40 has no lessons yet.

SELECT c.course_id, COUNT(*) AS total_lessons
FROM courses AS c
LEFT JOIN lessons AS l ON l.course_id = c.course_id
GROUP BY c.course_id
ORDER BY c.course_id;

Statement: "The row for course 40 shows total_lessons = 0, because course 40 has no lessons."', 'single_choice'::question_type, 'False. The LEFT JOIN keeps course 40 as one row whose lessons columns are all NULL. COUNT(*) counts rows, not lessons, so course 40 gets total_lessons = 1 (course 10 gets 3). COUNT(l.lesson_id) skips NULL values and returns 0 for course 40, which is the number you wanted. The common misconception is that COUNT(*) counts matches: it counts every row in the group, including the all-NULL row a LEFT JOIN adds for a parent without children.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_sdm_231') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_sdm_231'), 'Mai has finished 2 of the 3 lessons of SQL Basics. The progress query computes the percentage on SQLite, where both counts are integers:

SELECT 2 / 3 * 100 AS a,
       2 * 100 / 3 AS b;

Statement: "a is 0 and b is 66."', 'single_choice'::question_type, 'True. When both operands are integers, SQLite''s / is integer division and drops the fraction. In a, 2 / 3 is 0 and 0 * 100 is 0, so every learner who has not finished the whole course sees 0%. In b, 2 * 100 is 200 and 200 / 3 is 66, the percentage rounded down. PostgreSQL behaves the same way for integer operands. Writing 100.0 instead of 100 switches to real division (66.66...), and ROUND would then give 67, not 66. A common misconception is that SQL division always returns a fraction, as it does in JavaScript.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_sdm_231') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);

-- challenge chal_coding_sdm_232 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_sdm_232', (SELECT id FROM catalog.course WHERE public_id = 'sql-data-modeling'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'sql-data-modeling') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-sdm-2-3' AND is_deleted = false LIMIT 1), 'progress-per-course', 'Progress per course', 'Rewrite the query behind the "My courses" page. For the user bound to :user_id, return one row per course the user is enrolled in (any enrollment status, even if the same enrollment is stored twice): course_id, title, total_lessons (lessons of the course), completed_lessons (different lessons of the course this user finished; a lesson_progress row counts only when completed_at is not NULL) and percent (completed_lessons * 100 / total_lessons as a whole number rounded down, 0 when the course has no lessons). A course with no finished lesson must still appear with 0. Progress rows of other users and of courses the user is not enrolled in never count. Order by course_id. The test runner at the bottom of the file builds the tables from each test case (with PRAGMA foreign_keys = ON), runs QUERY with :user_id bound and prints the rows as a JSON list of lists, for example [[10, "SQL Basics", 3, 2, 66], [20, "Docker Basics", 4, 0, 0]].', 'open', 'easy'::difficulty_question, 'mini_coding', 30, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
