INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_sdm_232'), 1, 'Which table decides which courses appear on the page: the lessons the user has finished, or the courses the user is enrolled in? What happens to a course with no finished lesson if the query starts from lesson_progress?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_sdm_232'), 2, 'Look at three places: the condition on lesson_progress (in the ON clause of a LEFT JOIN, or in WHERE, where it removes the NULL rows the join kept), what COUNT(*) and COUNT(column) each count when one lesson has two progress rows, and what 2 / 3 * 100 and 2 * 100 / 3 return in SQLite. Then ask what x / 0 returns.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_sdm_232'), 3, 'A similar query on other tables: paid orders per customer, keeping customers with none. SELECT cu.customer_id, COUNT(DISTINCT o.order_id) AS paid_orders FROM customers AS cu LEFT JOIN orders AS o ON o.customer_id = cu.customer_id AND o.status = ''paid'' GROUP BY cu.customer_id. The status filter sits in ON, so a customer without paid orders keeps one row with NULLs and gets 0. COALESCE(expression, 0) turns a NULL result into 0.');
