    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_sdm_311'), 'Another version of the table declares the status like this:

status TEXT CHECK (status IN (''active'', ''completed'', ''cancelled''))

The import script runs:

INSERT INTO enrollments (user_id, course_id, enrolled_at, status)
VALUES (1, 10, ''2026-09-01 10:00:00'', NULL);

Statement: "The insert succeeds and the row is stored with status NULL."', 'single_choice'::question_type, 'True. A CHECK constraint only refuses a row when its expression is false. NULL IN (''active'', ''completed'', ''cancelled'') is NULL (unknown), not false, so the row passes the CHECK. SQLite and PostgreSQL both behave this way. To refuse a missing status, the column also needs NOT NULL. The common misconception is that a CHECK listing the allowed values also excludes NULL.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_sdm_311') AND order_index = 2)
    RETURNING id
)
