-- challenge chal_coding_sdm_312 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_sdm_312', (SELECT id FROM catalog.course WHERE public_id = 'sql-data-modeling'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'sql-data-modeling') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-sdm-3-1' AND is_deleted = false LIMIT 1), 'schema-that-refuses-bad-data', 'A schema that refuses bad data', 'Write SCHEMA, the CREATE TABLE statements for users, courses and enrollments, so that SQLite itself refuses the bad rows found in the CodeDev data audit. users(user_id INTEGER PRIMARY KEY, email, name): email required, unique ignoring case and containing ''@''; name required. courses(course_id INTEGER PRIMARY KEY, title, level): title required; level required and exactly ''beginner'', ''intermediate'' or ''advanced''. enrollments(user_id, course_id, enrolled_at, status): user_id and course_id required and must exist in users and courses; deleting a user deletes their enrollments; deleting a course that still has enrollments is refused; enrolled_at required; status required, exactly ''active'', ''completed'' or ''cancelled'', and ''active'' when an insert leaves it out; the same (user_id, course_id) pair at most once. Each test is a list of operations, {"op": "insert", "table": ..., "row": {...}} or {"op": "delete", "table": ..., "where": {...}} or {"op": "select", "table": ..., "columns": [...], "where": {...}}, which reads stored values back. The runner at the bottom of the file applies SCHEMA, runs PRAGMA foreign_keys = ON, executes the operations one by one and prints a JSON list with one result per operation: "ok", or the kind of constraint that refused it, "not_null", "unique", "check" or "foreign_key"; for a select, the matching rows as lists of values, such as [["active"]]. Example: ["ok", "unique", "check"].', 'open', 'easy'::difficulty_question, 'mini_coding', 30, true, false)
