INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_sdm_312'), 1, 'For each bad row in the audit, which kind of rule would have stopped it: a missing value, a duplicate, a value outside an allowed list, or a reference to a row that does not exist? Then ask what each of those rules does when the value is NULL.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_sdm_312'), 2, 'Everything goes in the column and table definitions: NOT NULL, UNIQUE, CHECK (...), DEFAULT ..., REFERENCES parent (column) ON DELETE ..., and a table-level PRIMARY KEY (a, b). Check three details in the SQLite docs: which collation UNIQUE uses to compare text, whether a CHECK fails when its expression is NULL, and whether a composite PRIMARY KEY in an ordinary SQLite table refuses NULL by itself.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_sdm_312'), 3, 'A similar table, not one of yours: CREATE TABLE lessons (lesson_id INTEGER PRIMARY KEY, course_id INTEGER NOT NULL REFERENCES courses (course_id) ON DELETE CASCADE, position INTEGER NOT NULL CHECK (position >= 1), title TEXT NOT NULL, slug TEXT NOT NULL COLLATE NOCASE, visibility TEXT NOT NULL DEFAULT ''draft'' CHECK (visibility IN (''draft'', ''published'')), UNIQUE (course_id, position), UNIQUE (course_id, slug)). Deleting a course deletes its lessons, positions start at 1, a slug is unique per course ignoring case, and a lesson inserted without visibility is a draft.');
