INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_sdm_321'), 1, 'When the driver runs in autocommit mode, where does each statement''s transaction start and end?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_sdm_321'), 2, 'Look at where BEGIN and COMMIT are (or are not) in each snippet, and at the point where the first write happens relative to the slow call.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_sdm_321'), 3, 'A similar case on other tables: a script runs UPDATE lessons SET position = position + 1, then INSERT INTO lessons ... fails on a NOT NULL column. Without BEGIN, the renumbering is already saved and stays saved. With BEGIN ... and a ROLLBACK in the error handler, the positions are back to what they were.');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_sdm_321'), 'The enrollment handler, before the fix (Python, sqlite3):

db = sqlite3.connect("codedev.db", isolation_level=None)   # autocommit
db.execute("INSERT INTO enrollments (user_id, course_id, enrolled_at, status) VALUES (?, ?, ?, ''active'')", (2, 10, now))
db.execute("INSERT INTO enrollment_events (user_id, course_id, event_type, source, created_at) VALUES (?, ?, ''enrolled'', ?, ?)", (2, 10, "ios", now))

The second call raises:
sqlite3.IntegrityError: CHECK constraint failed: source IN (''web'', ''android'', ''admin'')

Statement: "Because the second INSERT failed, SQLite also undid the first INSERT, so learner 2 has no enrollment row for course 10."', 'single_choice'::question_type, 'False. With isolation_level=None the driver never opens a transaction, so each statement runs in its own automatic transaction that commits as soon as the statement succeeds. The enrollment row was committed before the event insert even started, and nothing ties the two together. This is exactly how the half-written enrollments appeared. The common misconception is that a failure undoes ''the request''; the database only knows statements and transactions. To make the two inserts one unit, put them between BEGIN and COMMIT and roll back on error.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_sdm_321') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_sdm_321'), 'A proposed version of the handler:

BEGIN;
INSERT INTO enrollments (user_id, course_id, enrolled_at, status) VALUES (2, 10, ''2026-10-20 09:01:30'', ''active'');
-- the code now calls the email service over HTTP and waits for its answer (sometimes 10 s or more)
INSERT INTO enrollment_events (user_id, course_id, event_type, source, created_at) VALUES (2, 10, ''enrolled'', ''web'', ''2026-10-20 09:01:30'');
COMMIT;

The platform''s database is a single SQLite file shared by all request handlers.

Statement: "While this transaction waits for the email service, other connections that try to write to the database have to wait, and fail with ''database is locked'' once their busy timeout runs out."', 'single_choice'::question_type, 'True. SQLite allows one writer at a time for the whole database file. After the first INSERT, this transaction holds the write lock until COMMIT or ROLLBACK, so every other writer waits (up to its busy_timeout) and then gets SQLITE_BUSY, ''database is locked''. WAL mode lets readers keep reading, but it does not allow a second writer. In PostgreSQL other sessions could still write other rows, but this transaction would keep its row locks and its connection busy for the whole call. Either way the fix is the same: never wait on a network call inside a transaction. Commit first, then send the email (here the enrollment_events row is what the email job reads).', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_sdm_321') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);

-- challenge chal_coding_sdm_322 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_sdm_322', (SELECT id FROM catalog.course WHERE public_id = 'sql-data-modeling'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'sql-data-modeling') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-sdm-3-2' AND is_deleted = false LIMIT 1), 'enroll-in-one-transaction', 'Enroll in one transaction', 'Enrolling a learner writes two rows: the enrollment, and an ''enrolled'' row in enrollment_events that the welcome-email job reads. Requests from the new iOS app send source = ''ios'', which the CHECK on enrollment_events.source rejects, and because each statement commits on its own, the enrollment row stays behind without its event. Fix ENROLL, a list of SQL statements that the runner executes in order for every request with the named parameters :user_id, :course_id, :at and :source, so that both rows are saved or neither is. Contract: keep both INSERT statements as they are; a request that fails at any statement leaves no row; a request that succeeds is committed before the next one starts. The runner opens the connection with isolation_level=None (the Python driver never starts or commits a transaction on its own), turns on PRAGMA foreign_keys, stops a request at the first error and executes ROLLBACK if a transaction is still open. It prints {"requests": [one outcome per request: "ok", "not_committed" (still inside a transaction at the end) or the error class such as "IntegrityError"], "enrollments": [[user_id, course_id, enrolled_at, status], ...] ordered by user_id, course_id, "events": [[user_id, course_id, event_type, source], ...] in insertion order}.', 'open', 'easy'::difficulty_question, 'mini_coding', 30, true, false)
