INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_sdm_332', (SELECT id FROM catalog.course WHERE public_id = 'sql-data-modeling'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'sql-data-modeling') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-sdm-3-3' AND is_deleted = false LIMIT 1), 'stop-duplicate-enrollment', 'Stop Duplicate Enrollment', 'Symptom: learner 1042 double-tapped Enroll and now has two active enrollments in course 7; the progress report counts them twice. Both requests ran the application''s check (SELECT count(*) of active or completed enrollments for the pair) before either inserted, and ENROLL inserts blindly. Fix SCHEMA and ENROLL (one statement, named parameters :user_id, :course_id, :at) so the database itself guarantees one enrollment per (user_id, course_id): a duplicate request never fails and never adds a row; an existing ''cancelled'' enrollment is reactivated (status ''active'', enrolled_at = :at); an ''active'' or ''completed'' one is left unchanged. A user can still enroll in other courses and a course still takes other users. The runner (do not change it) creates users, courses and existing enrollments, then replays bursts of requests: for every request of a burst it runs the application''s check first, then ENROLL for each request whose check found nothing. Responses: "enrolled" (a row was inserted), "reactivated" (a cancelled row was changed), "already_enrolled" (the check found a row, or ENROLL changed 0 rows) or the error class name if ENROLL raised one. The connection uses isolation_level=None (every statement is its own transaction) with PRAGMA foreign_keys = ON. It prints {"responses": [...], "enrollments": [[user_id, course_id, enrolled_at, status], ...]} ordered by user_id, course_id, enrolled_at.', 'open', 'easy'::difficulty_question, 'fix_bug', 30, true, false)
